import com.lingiot.demo.Wire;
import java.nio.charset.StandardCharsets;
import java.util.*;
public class WireTest {public static void main(String[] a){Wire w=new Wire();List<String> out=new ArrayList<>();byte[] b="{\"字\":1}\nabc\n".getBytes(StandardCharsets.UTF_8);for(byte x:b)w.feed(new byte[]{x},out::add);if(!out.equals(List.of("{\"字\":1}","abc")))throw new AssertionError(out);w.feed(("a".repeat(1025)+"\nOK\n").getBytes(StandardCharsets.UTF_8),out::add);if(!out.equals(List.of("{\"字\":1}","abc","OK")))throw new AssertionError(out);w.feed(("b".repeat(1024)+"\n").getBytes(StandardCharsets.UTF_8),out::add);if(out.size()!=4||out.get(3).length()!=1024)throw new AssertionError("1024-byte frame boundary");for(String ip:List.of("10.0.0.1","172.16.0.1","192.168.4.1","172.31.0.2"))if(!Wire.privateIp(ip))throw new AssertionError(ip);for(String ip:List.of("127.0.0.1","172.32.0.1","8.8.8.8","192.168.4.1:80","10.0.0.256","010.1.1.1"))if(Wire.privateIp(ip))throw new AssertionError(ip);System.out.println("Wire tests passed");}}
